const canvas=document.getElementById('game'),ctx=canvas.getContext('2d');
const W=960,H=590; let coins=420,lives=3,wave=1,playing=false,spawned=0,spawnTimer=0,last=0,speed=1,selectedType=null,hoverPad=null,toastTimer=0;
const types={scout:{name:'Scout Seat',icon:'◉',cost:80,damage:14,rate:1.0,range:105,color:'#51e1d0',desc:'Fast splash pulses'},sonic:{name:'Sonic Bowl',icon:'◒',cost:140,damage:31,rate:1.5,range:130,color:'#c184ff',desc:'Piercing sound blast'},tank:{name:'Tank Throne',icon:'♜',cost:210,damage:62,rate:2.1,range:115,color:'#f4c95d',desc:'Heavy single target'},drone:{name:'Drain Drone',icon:'✦',cost:275,damage:19,rate:.38,range:170,color:'#6ca4ff',desc:'Rapid aerial fire'}}};
const pads=[{x:170,y:175},{x:355,y:130},{x:535,y:205},{x:770,y:155},{x:255,y:390},{x:470,y:430},{x:710,y:375},{x:850,y:470}]; let towers=[];let enemies=[];let particles=[];
const path=[{x:-25,y:294},{x:110,y:294},{x:110,y:450},{x:330,y:450},{x:330,y:290},{x:570,y:290},{x:570,y:470},{x:790,y:470},{x:790,y:300},{x:990,y:300}];
function lerp(a,b,t){return a+(b-a)*t} function posOnPath(t){let total=0,lens=[];for(let i=1;i<path.length;i++){let d=Math.hypot(path[i].x-path[i-1].x,path[i].y-path[i-1].y);lens.push(d);total+=d}let d=t*total;for(let i=1;i<path.length;i++){if(d<=lens[i-1]){let q=d/lens[i-1];return{x:lerp(path[i-1].x,path[i].x,q),y:lerp(path[i-1].y,path[i].y,q)}}d-=lens[i-1]}return path.at(-1)}
function log(msg){let el=document.getElementById('log'),row=document.createElement('div');row.className='log-line';row.innerHTML='<b>●</b> '+msg+' <em>now</em>';el.prepend(row);while(el.children.length>4)el.lastChild.remove()}
function flash(t){let el=document.getElementById('toast');el.textContent=t;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),1800)}
function draw(){ctx.clearRect(0,0,W,H);let grad=ctx.createLinearGradient(0,0,W,H);grad.addColorStop(0,'#112433');grad.addColorStop(1,'#0a1721');ctx.fillStyle=grad;ctx.fillRect(0,0,W,H);
 // subtle district grid
 ctx.strokeStyle='#1a3240';ctx.lineWidth=1;for(let x=0;x<W;x+=32){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,H);ctx.stroke()}for(let y=0;y<H;y+=32){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(W,y);ctx.stroke()}
 // neon district accents
 ctx.fillStyle='#183546';ctx.fillRect(28,38,190,2);ctx.fillRect(742,530,160,2);ctx.fillStyle='#2e5960';ctx.font='10px DM Sans';ctx.fillText('FLUSHLINE / 07',30,29);ctx.fillText('SEWER CORE // 02',756,522);
 // path shadow and road
 ctx.lineCap='round';ctx.lineJoin='round';drawPath('#061018',54);drawPath('#213342',42);drawPath('#172837',34);ctx.setLineDash([11,13]);drawPath('#49606d',2);ctx.setLineDash([]);
 // path markers
 path.slice(1,-1).forEach(p=>{ctx.fillStyle='#587080';ctx.fillRect(p.x-2,p.y-2,4,4)});
 pads.forEach((p,i)=>{let occupied=towers.some(t=>t.pad===i);ctx.beginPath();ctx.arc(p.x,p.y,25,0,Math.PI*2);ctx.fillStyle=occupied?'#122a36':(hoverPad===i&&selectedType?'#214a50':'#142734');ctx.fill();ctx.strokeStyle=occupied?types[towers.find(t=>t.pad===i).type].color:(selectedType?'#3b777c':'#304a58');ctx.lineWidth=1.5;ctx.stroke();if(!occupied){ctx.fillStyle='#63808b';ctx.font='20px DM Sans';ctx.textAlign='center';ctx.fillText('+',p.x,p.y+7);ctx.textAlign='left'}});
 towers.forEach(drawTower);enemies.forEach(drawEnemy);particles.forEach(drawParticle);if(playing&&spawned<6+wave*2){ctx.fillStyle='#8ba4b4';ctx.font='10px DM Sans';ctx.fillText('INCOMING // '+(6+wave*2-spawned)+' HOSTILES',30,560)} }
function drawPath(c,w){ctx.beginPath();ctx.moveTo(path[0].x,path[0].y);path.slice(1).forEach(p=>ctx.lineTo(p.x,p.y));ctx.strokeStyle=c;ctx.lineWidth=w;ctx.stroke()}
function drawTower(t){let p=pads[t.pad],d=types[t.type];if(t.flash>0){ctx.beginPath();ctx.arc(p.x,p.y,d.range,0,Math.PI*2);ctx.fillStyle=d.color+'13';ctx.fill();ctx.strokeStyle=d.color+'70';ctx.stroke()}ctx.save();ctx.translate(p.x,p.y);ctx.shadowColor=d.color;ctx.shadowBlur=14;ctx.fillStyle='#0b1720';ctx.strokeStyle=d.color;ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,0,18,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.shadowBlur=0;ctx.fillStyle=d.color;ctx.font='bold 21px DM Sans';ctx.textAlign='center';ctx.fillText(d.icon,0,7);ctx.fillStyle='#8aa1af';ctx.font='8px DM Sans';ctx.fillText('LV '+t.level,0,30);ctx.restore();}
function drawEnemy(e){let p=posOnPath(e.t);ctx.save();ctx.translate(p.x,p.y);ctx.shadowColor=e.color;ctx.shadowBlur=12;ctx.fillStyle=e.color;ctx.beginPath();ctx.arc(0,0,e.size,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;ctx.fillStyle='#101b28';ctx.beginPath();ctx.arc(-e.size*.35,-2,2,0,7);ctx.arc(e.size*.35,-2,2,0,7);ctx.fill();ctx.strokeStyle='#f9c4a0';ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,3,e.size*.4,0,Math.PI);ctx.stroke();ctx.fillStyle='#0b121a';ctx.fillRect(-e.size,-e.size-9,e.size*2,3);ctx.fillStyle='#f37890';ctx.fillRect(-e.size,-e.size-9,e.size*2*(e.hp/e.max),3);ctx.restore()}
function drawParticle(p){ctx.globalAlpha=p.life;ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,7);ctx.fill();ctx.globalAlpha=1}
function spawn(){let elite=spawned%7===6;let hp=55+wave*24;let e={t:0,hp:elite?hp*3:hp,max:elite?hp*3:hp,size:elite?15:10,color:elite?'#f4c95d':'#ff789b',speed:(.018+wave*.002)*(elite?.62:1),reward:elite?55:15};enemies.push(e);spawned++;if(elite)log('ELITE BUBBLE detected');}
function attack(t,dt){t.cool-=dt;if(t.cool>0)return;let d=types[t.type],p=pads[t.pad],target=null,lead=-1;enemies.forEach(e=>{let q=posOnPath(e.t),dist=Math.hypot(q.x-p.x,q.y-p.y);if(dist<d.range&&e.t>lead){target=e;lead=e.t}});if(target){target.hp-=d.damage; t.cool=d.rate; t.flash=.14;let q=posOnPath(target.t);for(let i=0;i<5;i++)particles.push({x:q.x,y:q.y,r:Math.random()*3+2,life:.35,color:d.color,vx:(Math.random()-.5)*35,vy:(Math.random()-.5)*35});}}
function update(dt){let dt2=dt*speed; if(playing){if(spawned<6+wave*2){spawnTimer-=dt2;if(spawnTimer<=0){spawn();spawnTimer=Math.max(.35,1.05-wave*.04)}}enemies.forEach(e=>e.t+=e.speed*dt2);towers.forEach(t=>attack(t,dt2));let gone=enemies.filter(e=>e.t>=1);if(gone.length){lives-=gone.length;document.getElementById('lives').textContent=lives;log('Core impact! -'+gone.length+' HP');enemies=enemies.filter(e=>e.t<1);if(lives<=0){playing=false;flash('CORE BREACHED — refresh to retry')}}let defeated=enemies.filter(e=>e.hp<=0);if(defeated.length){defeated.forEach(e=>{coins+=e.reward;for(let i=0;i<8;i++)particles.push({x:posOnPath(e.t).x,y:posOnPath(e.t).y,r:3,life:.7,color:'#f4c95d',vx:(Math.random()-.5)*80,vy:(Math.random()-.5)*80})});enemies=enemies.filter(e=>e.hp>0);document.getElementById('coins').textContent=coins}if(spawned>=6+wave*2&&enemies.length===0){playing=false;if(wave<10){wave++;document.getElementById('wave').textContent=wave+'/10';log('Wave cleared. Bonus +40 gems');coins+=40;document.getElementById('coins').textContent=coins;flash('WAVE CLEAR — +40 GEMS')}else flash('DISTRICT SECURED')}}towers.forEach(t=>{t.flash=Math.max(0,t.flash-dt2)});particles.forEach(p=>{p.life-=dt2/1.5;p.x+=p.vx*dt2;p.y+=p.vy*dt2});particles=particles.filter(p=>p.life>0);draw();requestAnimationFrame(loop)}
function loop(ts){let dt=Math.min(.05,(ts-last)/1000||0);last=ts;update(dt)}
function deploy(type){let i=pads.findIndex((p,n)=>!towers.some(t=>t.pad===n));if(i<0){flash('ALL DEPLOYMENT PADS OCCUPIED');return}if(coins<types[type].cost){flash('NOT ENOUGH GEMS');return}coins-=types[type].cost;document.getElementById('coins').textContent=coins;towers.push({type,pad:i,level:1,cool:.2,flash:0});log(types[type].name+' deployed');selectedType=null;renderUnits();renderSelected();flash('UNIT DEPLOYED');}
function renderUnits(){let el=document.getElementById('unitList');el.innerHTML='';Object.entries(types).forEach(([key,d])=>{let row=document.createElement('div');row.className='unit '+(coins<d.cost?'disabled':'')+(selectedType===key?' chosen':'');row.innerHTML=`<div class="unit-art" style="color:${d.color}">${d.icon}</div><div class="unit-info"><strong>${d.name}</strong><small>${d.desc}</small></div><b class="cost">✦ ${d.cost}</b>`;row.onclick=()=>{if(coins>=d.cost){selectedType=selectedType===key?null:key;renderUnits();renderSelected();flash(selectedType?'Click a glowing pad to deploy':'Selection cleared')}};el.appendChild(row)})}
function renderSelected(){let title=document.getElementById('selectedTitle'),cost=document.getElementById('selectedCost'),body=document.getElementById('selectedBody');if(!selectedType){title.textContent='SELECT A UNIT';cost.textContent='DEPLOY';body.className='empty-state';body.innerHTML='<div class="empty-icon">⌖</div><p>Choose a guardian from the roster<br>to deploy it on the grid.</p>';return}let d=types[selectedType];title.textContent=d.name.toUpperCase();cost.textContent='✦ '+d.cost;body.className='';body.innerHTML=`<div class="detail"><div><b>${d.damage}</b><span>damage</span></div><div><b>${d.range}</b><span>range</span></div><div><b>${d.rate}s</b><span>cooldown</span></div><div><b>${d.desc}</b><span>role</span></div></div><button class="deploy" id="deployBtn">DEPLOY TO NEXT PAD</button>`;document.getElementById('deployBtn').onclick=()=>deploy(selectedType)}
canvas.addEventListener('mousemove',e=>{let r=canvas.getBoundingClientRect(),x=(e.clientX-r.left)*W/r.width,y=(e.clientY-r.top)*H/r.height;let n=pads.findIndex(p=>Math.hypot(p.x-x,p.y-y)<28);if(n!==hoverPad){hoverPad=n;draw()}});canvas.addEventListener('click',e=>{if(hoverPad>=0&&selectedType&&!towers.some(t=>t.pad===hoverPad)){let d=types[selectedType];if(coins>=d.cost){coins-=d.cost;document.getElementById('coins').textContent=coins;towers.push({type:selectedType,pad:hoverPad,level:1,cool:.2,flash:0});log(d.name+' deployed on pad '+String(hoverPad+1).padStart(2,'0'));selectedType=null;renderUnits();renderSelected();flash('UNIT DEPLOYED')}else flash('NOT ENOUGH GEMS')}});
document.getElementById('startBtn').onclick=()=>{playing=true;spawned=0;spawnTimer=.1;document.getElementById('startOverlay').style.display='none';log('Wave '+wave+' incoming — hold the line');flash('WAVE '+wave+' STARTED')};document.querySelectorAll('[data-speed]').forEach(b=>b.onclick=()=>{speed=+b.dataset.speed;document.querySelectorAll('[data-speed]').forEach(x=>x.classList.toggle('active',x===b))});
renderUnits();renderSelected();log('Grid online. Awaiting deployment');draw();requestAnimationFrame(loop);

